package dev.thillainirmal.cloudpulse;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api")
public class PulseController{private final PulseAnalyzer a;private final PrometheusGateway prometheus;public PulseController(PulseAnalyzer a,PrometheusGateway prometheus){this.a=a;this.prometheus=prometheus;}@PostMapping("/analyze")public PulseAnalyzer.Analysis analyze(@RequestBody PulseAnalyzer.Snapshot s){return a.analyze(s);}@GetMapping("/live/{namespace}/{workload}")public Map<String,Object> live(@PathVariable String namespace,@PathVariable String workload){var snapshot=prometheus.snapshot(namespace,workload);return Map.of("source","prometheus","snapshot",snapshot,"analysis",a.analyze(snapshot));}@GetMapping("/demo")public Map<String,Object> demo(){var s=new PulseAnalyzer.Snapshot("payments","fraud-engine",91,94,8.7,1240,5);return Map.of("source","explicit synthetic demo","snapshot",s,"analysis",a.analyze(s),"topology",List.of("gateway","payments-api","fraud-engine","postgres"));}}
